name: Auto‑approve workflows for first‑time contributors

on:
  pull_request_target:
    types: [labeled, synchronize]
    branches: [main, release-**]

permissions:
  contents: read

jobs:
  approve:
    runs-on: ubuntu-latest
    permissions:
      actions: write
    env:
      GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
    steps:
      - name: Check if approval is needed
        id: check
        uses: actions/github-script@v6
        with:
          script: |
            const core = require('@actions/core');
            const github = require('@actions/github');
            const context = github.context;

            const author = context.payload.pull_request.user.login;
            const owner = context.repo.owner;
            const repo = context.repo.repo;

            // Determine if the PR has the ok-to-test label
            let labelOk = false;
            if (context.payload.action === 'labeled' && context.payload.label.name === 'ok-to-test') {
              labelOk = true;
            } else if (context.payload.action === 'synchronize') {
              const labels = await github.rest.issues.listLabelsOnIssue({
                owner,
                repo,
                issue_number: context.payload.pull_request.number,
              });
              labelOk = labels.data.some(l => l.name === 'ok-to-test');
            }

            // Count all PRs by this author
            const searchResult = await github.rest.search.issuesAndPullRequests({
              q: `repo:${owner}/${repo} author:${author} type:pr`,
              per_page: 1,
            });
            const total = searchResult.data.total_count;
            const returning = total > 1;

            // Approve if returning contributor or ok-to-test label present
            const approve = returning || labelOk;
            core.setOutput('approve', approve ? 'true' : 'false');

      - name: Approve pending workflow runs
        if: steps.check.outputs.approve == 'true'
        uses: actions/github-script@v6
        with:
          script: |
            const github = require('@actions/github');
            const context = github.context;

            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const pr = context.payload.pull_request;
            const sha = pr.head.sha;

            // List all workflow runs for this PR
            const runs = await github.rest.actions.listWorkflowRunsForRepo({
              owner,
              repo,
              event: 'pull_request',
              head_sha: sha,
              per_page: 100,
            });

            // Approve any queued runs that are awaiting approval
            for (const run of runs.data.workflow_runs) {
              if (run.status === 'queued' && run.conclusion === null) {
                await github.rest.actions.approveWorkflowRun({
                  owner,
                  repo,
                  run_id: run.id,
                });
              }
            }
